async (page) => {
  const sel = 'li, [role=listitem]';
  const list = page.getByRole('list', {name:'Inventory'});
  for (let i=0;i<400;i++){
    const t = page.locator('code', {hasText:'HAK-5638'});
    if (await t.count()) {
      const item = page.getByRole('listitem').filter({has: t});
      await item.getByRole('button',{name:'Select'}).click();
      return 'clicked at step '+i+': '+await item.innerText();
    }
    await list.evaluate(el=>{ let s=el; while(s && s.scrollHeight<=s.clientHeight+5) s=s.parentElement; (s||document.scrollingElement).scrollTop += 400; });
    await page.waitForTimeout(50);
  }
  return 'not found';
}

